class Solution:
    def minPatches(self, nums: List[int], n: int) -> int:
        reach = 0
        patches = 0
        for x in nums:
            if x > n:
                break
            while x > reach + 1:
                reach += reach + 1
                patches += 1
            reach += x
            if reach >= n:
                return patches
        while reach < n:
            reach += reach + 1
            patches += 1
        return patches

