#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int minPatches(int* nums, int numsSize, int n) {
    long long reach = 0;
    int patches = 0;
    for (int i=0; i<numsSize; ++i) {
        long long x = nums[i];
        if (x > n) break;
        while (x > reach + 1) {
            reach += reach + 1;
            ++patches;
        }
        reach += x;
        if (reach >= n) return patches;
    }
    while (reach < n) {
        reach += reach + 1;
        ++patches;
    }
    return patches;
}

