public class Main {
    static int[] parseNums(String s) {
        int first = s.indexOf('[', 1);
        int end = s.indexOf(']', first);
        String body = s.substring(first + 1, end).trim();
        if (body.isEmpty()) return new int[0];
        String[] parts = body.split(",");
        int[] a = new int[parts.length];
        for (int i=0;i<parts.length;i++) a[i]=Integer.parseInt(parts[i].trim());
        return a;
    }
    static int parseN(String s) {
        int end = s.indexOf(']', s.indexOf('[',1));
        String tail = s.substring(end + 1).replaceAll("[^0-9]", "").trim();
        return Integer.parseInt(tail);
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int[] nums = parseNums(line);
        int n = parseN(line);
        System.out.println(new Solution().minPatches(nums,n));
    }
}

